// <autogenerated/>
using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Web.Mvc;

namespace Fanex.LiveCasino.CoreSetting.Web.App_Start
{
    public class RouteConfig
    {
        public static void RegisterRoutes(string areaName, AreaRegistrationContext context)
        {
            context.MapRoute(
                areaName + "_Default",
                "LiveCasinoSetting/{controller}/{action}/{id}",
                new
                {
                    controller = "LiveCasinoUser",
                    action = "UnAuthorized",
                    id = UrlParameter.Optional
                },
                new[] 
                    {
                        typeof (Fanex.LiveCasino.CoreSetting.Controllers.LiveCSSettingController).Namespace,
                        typeof (Fanex.LiveCasino.CoreSetting.Controllers.LiveCasinoUserController).Namespace
                    });
        }
    }
}